WITH lines AS (SELECT id, host, log_ts, level, key, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, value) SELECT id, log_ts, level, key, value, ROW_NUMBER() OVER w_running AS seq_no, FIRST_VALUE(key) IGNORE NULLS OVER w_ordered AS first_known_key, FIRST_VALUE(key) IGNORE NULLS OVER w_ordered AS first_known_key_2 FROM lines WINDOW w_running AS (PARTITION BY host, level ORDER BY log_ts DESC, id, key), w_ordered AS (PARTITION BY level ORDER BY log_ts, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
